begin;
select plan(23);
insert into auth.users(id,aud,role,email,email_confirmed_at) values
('71000000-0000-4000-8000-000000000001','authenticated','authenticated','phone-one@example.test',now()),
('71000000-0000-4000-8000-000000000002','authenticated','authenticated','phone-two@example.test',now());
select ok(not has_function_privilege('authenticated','public.member_phone_operation(text,uuid,text,text,uuid,text)','EXECUTE'),'members cannot invoke protected phone operations');
select ok(not has_table_privilege('authenticated','private.member_phone_verifications','INSERT'),'members cannot manufacture verification proof');
select set_config('request.jwt.claims','{"role":"service_role"}',true);
select is(public.member_phone_operation('status','71000000-0000-4000-8000-000000000001')->>'verified','false','no proof initially');
select lives_ok($$select public.member_phone_operation('start','71000000-0000-4000-8000-000000000001','+919000000001','whatsapp')$$,'start authenticated intent');
select is(public.member_phone_operation('start','71000000-0000-4000-8000-000000000001','+919000000001','sms')->>'error','rate_limited','fallback shares account cooldown');
select is(public.member_phone_operation('claim_hook','71000000-0000-4000-8000-000000000001','+919000000099',p_hook_id=>'wrong')->>'error','verification_changed','wrong hook target blocked');
select is(public.member_phone_operation('verify','71000000-0000-4000-8000-000000000001')->>'error','verification_changed','unsent code cannot be verified');
select is(public.member_phone_operation('claim_hook','71000000-0000-4000-8000-000000000001','+919000000001',p_hook_id=>'hook-one')->>'channel','whatsapp','hook uses protected channel');
select is(public.member_phone_operation('claim_hook','71000000-0000-4000-8000-000000000001','+919000000001',p_hook_id=>'hook-one')->>'error','verification_changed','duplicate hook not sent twice');
select public.member_phone_operation('sent','71000000-0000-4000-8000-000000000001',p_intent=>(select id from private.member_phone_intents where user_id='71000000-0000-4000-8000-000000000001'),p_hook_id=>'hook-one');
update auth.users set phone_change='919000000001' where id='71000000-0000-4000-8000-000000000001';
select public.member_phone_operation('verify','71000000-0000-4000-8000-000000000001');
select is(public.member_phone_operation('complete','71000000-0000-4000-8000-000000000001',p_intent=>(select id from private.member_phone_intents where user_id='71000000-0000-4000-8000-000000000001'))->>'error','verification_changed','intent alone never creates proof');
update auth.users set phone='919000000001',phone_confirmed_at=now() where id='71000000-0000-4000-8000-000000000001';
select is(public.member_phone_operation('complete','71000000-0000-4000-8000-000000000001',p_intent=>(select id from private.member_phone_intents where user_id='71000000-0000-4000-8000-000000000001'))->>'verified','true','matching auth-confirmed phone creates proof');
select is(public.member_phone_operation('complete','71000000-0000-4000-8000-000000000001',p_intent=>(select id from private.member_phone_intents where user_id='71000000-0000-4000-8000-000000000001'))->>'error','verification_changed','completion cannot replay');
select is(public.member_phone_operation('start','71000000-0000-4000-8000-000000000002','+919000000001','whatsapp')->>'error','unavailable','phone proof belongs to one account');
update private.member_phone_intents set resend_available_at=now()-interval '1 second' where user_id='71000000-0000-4000-8000-000000000001';
select is(public.member_phone_operation('start','71000000-0000-4000-8000-000000000001','+919000000003','whatsapp')->>'verified','false','replacement cannot display previous proof as verified');
select is(public.member_phone_operation('claim_hook','71000000-0000-4000-8000-000000000001','+919000000003',p_hook_id=>'hook-one')->>'error','verification_changed','hook receipt survives a replacement intent');
select is((select phone from private.member_phone_verifications where user_id='71000000-0000-4000-8000-000000000001'),'+919000000001','old proof is preserved for the old phone');
select is(public.member_phone_operation('complete','71000000-0000-4000-8000-000000000001',p_intent=>'71000000-0000-4000-8000-000000000099')->>'error','verification_changed','stale intent completion blocked');
update private.member_phone_intents set expires_at=now()-interval '1 second' where user_id='71000000-0000-4000-8000-000000000001';
select is(public.member_phone_operation('claim_hook','71000000-0000-4000-8000-000000000001','+919000000003',p_hook_id=>'expired')->>'error','verification_changed','expired delivery blocked');
select is(public.member_phone_operation('verify','71000000-0000-4000-8000-000000000001')->>'error','verification_changed','expired verification blocked');
update auth.users set phone_change='919000000003' where id='71000000-0000-4000-8000-000000000001';
update private.member_phone_intents set expires_at=now()+interval '5 minutes',delivered=true,attempts=5 where user_id='71000000-0000-4000-8000-000000000001';
select is(public.member_phone_operation('verify','71000000-0000-4000-8000-000000000001')->>'error','rate_limited','five code attempts maximum');
update private.member_phone_intents set resend_available_at=now()-interval '1 second' where user_id='71000000-0000-4000-8000-000000000001';
update private.member_phone_limits set attempts=5 where key='account:71000000-0000-4000-8000-000000000001';
select is(public.member_phone_operation('start','71000000-0000-4000-8000-000000000001','+919000000003','sms')->>'error','rate_limited','hourly account cap persists across target/channel changes');
update auth.users set phone='919000000099' where id='71000000-0000-4000-8000-000000000001';
select is(public.member_phone_operation('status','71000000-0000-4000-8000-000000000001')->>'verified','false','auth account phone change immediately invalidates old proof');
select set_config('request.jwt.claims','{"role":"authenticated"}',true);
select throws_ok($$select public.member_phone_operation('status','71000000-0000-4000-8000-000000000001')$$,'42501','Service only','function also enforces service identity');
select * from finish();
rollback;
